    });
    let token = sign_jwt(&stale_key, "stale-key", &claims);

    let validator = TokenValidator::new();
    let result = validator.validate(&token, &mock_issuer, TEST_RESOURCE).await;
    assert!(
        result.is_err(),
        "token signed with removed key must be rejected"
